function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof TRAVANCORE_FROG_INFO&&(n.innerHTML=TRAVANCORE_FROG_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderTaxonomy(){const n=document.getElementById("taxonomy-grid");n&&"undefined"!=typeof TAXONOMY_DATA&&(n.innerHTML=Object.entries(TAXONOMY_DATA).map(([n,e])=>`\n        <div class="tax-card">\n            <span class="tax-lbl">${n.toUpperCase()}:</span>\n            <span class="tax-val">${e}</span>\n        </div>\n    `).join(""))}function renderEcology(){if("undefined"==typeof ECOLOGY_BEHAVIOUR)return;const n=document.getElementById("eco-intro"),e=document.getElementById("eco-dist"),t=document.getElementById("eco-habitat"),o=document.getElementById("eco-morph"),r=document.getElementById("eco-behaviour"),i=document.getElementById("eco-diet"),d=document.getElementById("eco-repro"),a=document.getElementById("eco-conserve");n&&(n.innerHTML=`<strong>Introduction:</strong> ${ECOLOGY_BEHAVIOUR.introduction}`),e&&(e.innerHTML=`<strong>Distribution Range:</strong> ${ECOLOGY_BEHAVIOUR.distribution}`),t&&(t.innerHTML=`<strong>Rainforest Habitat:</strong> ${ECOLOGY_BEHAVIOUR.habitat}`),o&&(o.innerHTML=`<strong>Morphology & Webbing:</strong> ${ECOLOGY_BEHAVIOUR.morphology}`),r&&(r.innerHTML=`<strong>Arboreal Parachuting Behaviour:</strong> ${ECOLOGY_BEHAVIOUR.behaviour}`),i&&(i.innerHTML=`<strong>Diet & Canopy Hunting:</strong> ${ECOLOGY_BEHAVIOUR.diet}`),d&&(d.innerHTML=`<strong>Foam Nesting & Reproduction:</strong> ${ECOLOGY_BEHAVIOUR.reproduction}`),a&&(a.innerHTML=`<strong>Conservation Status & Threats:</strong> ${ECOLOGY_BEHAVIOUR.conservation}`)}function renderFacts(){const n=document.getElementById("facts-grid");n&&"undefined"!=typeof INTERESTING_FACTS&&(n.innerHTML=INTERESTING_FACTS.map(n=>`\n        <div class="fact-card">\n            <h3>✨ ${n.title}</h3>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTaxonomy(),renderEcology(),renderFacts(),renderGallery(),renderReferences(),initThemeToggle()});